template.query:
mutation CreateUniqueNode($input: CreateNodeInput!) {
        createNode(input: $input) {
          success
          node {
            id
            content
            createdAt
            updatedAt
            attributes {
              id
              value
              attribute {
                id
                identifier
                dataType
              }
            }
          }
          errors {
            message
            field
          }
        }
      }
